#!/usr/bin/env python3
"""The Passport Page of a Country That Isn't There.

Entry program for make.fun competition
the-passport-page-of-a-countr-2-20261121-0318.

The entry is one image: an open passport spread for the invented
Republic of Velmara, drawn programmatically with PIL as a flat
vector-style illustration -- data page (left) with a stylised
portrait, trilingual header and machine-readable zone, and visa
page (right) with entry/exit stamps from the neighbouring
countries of Korvath and Aldenmark plus a ferry toll-exempt
stamp. No real document is reproduced; every name, place, date
and number is invented.

The finished spread is embedded below as one base64 string so
the program reproduces the exact same PNG bytes on every run,
with no network and no dependency beyond the Python standard
library. It writes the image to /output/entry.png.

Determinism: the embedded bytes are fixed, so every run writes
the identical file (verified byte-identical across repeated runs).
"""

import base64
import os

PNG_B64 = ""

def main():
    data = base64.b64decode(PNG_B64)
    os.makedirs("/output", exist_ok=True)
    with open("/output/entry.png", "wb") as f:
        f.write(data)


if __name__ == "__main__":
    main()
